118	// encodeFile 把内存状态编码为完整文件字节。
119	func encodeFile(st *mapState) ([]byte, error) {
120		fd := fileData{
121			Version:       int(fileVersion),
122			Config:        st.config,
123			Trajectory:    st.trajectory,
124			Landmarks:     make([]landmarkJSON, 0, len(st.landmarks)),
125			Segments:      make([]segmentJSON, 0, len(st.segments)),
126			Sources:       make([]*frameSrcJSON, len(st.sources)),
127			Corrections:   make([]corrRecJSON, 0, len(st.corrections)),
128			Invalidations: make([]invalJSON, 0, len(st.invalRecords)),
129		}
130		for id, lm := range st.landmarks {
131			lj := landmarkJSON{ID: id, Occurrences: make([]occurrenceJSON, 0, len(lm.appearances))}
132			for i, occ := range lm.appearances {
133				oj := occurrenceJSON{
134					Number:        i + 1,
135					X:             occ.x,
136					Y:             occ.y,
137					Count:         occ.count,
138					LegacyCount:   occ.legacyCount,
139					LegacyMX:      occ.legacyMX,
140					LegacyMY:      occ.legacyMY,
141					FirstSeenTime: occ.firstSeenTime,
142					HasFirstSeen:  occ.hasFirstSeen,
143					Active:        occ.active,
144				}
145				if !occ.active {
146					oj.InvalidTime = occ.invalidTime
147					oj.InvalidReason = occ.invalidReason
148					oj.InvalidOpID = occ.invalidOpID
149				}
150				lj.Occurrences = append(lj.Occurrences, oj)
151			}
152			fd.Landmarks = append(fd.Landmarks, lj)
153		}
154		for id, rec := range st.segments {
155			fd.Segments = append(fd.Segments, segmentJSON{ID: id, Hash: rec.hash, Result: rec.result})
156		}
157		for k, src := range st.sources {
158			if src == nil {
159				continue // 旧文件帧在新文件中保留为 null，表示仍无逐帧依据
160			}
161			obs := append([]Observation(nil), src.observations...)
162			fd.Sources[k] = &frameSrcJSON{MoveVariance: src.moveVariance, Observations: obs}
163		}
164		for _, rec := range st.corrections {
165			cj := corrRecJSON{
166				ID:        rec.ID,
167				Anchor:    rec.Anchor,
168				Target:    rec.Target,
169				EndTime:   rec.EndTime,
170				Poses:     make([]poseChangeJSON, len(rec.Poses)),
171				Landmarks: make([]landmarkChangeJSON, len(rec.Landmarks)),
172			}
173			for i, pc := range rec.Poses {
174				cj.Poses[i] = poseChangeJSON{Before: pc.Before, After: pc.After}
175			}
176			for i, lc := range rec.Landmarks {
177				cj.Landmarks[i] = landmarkChangeJSON{ID: lc.ID, Occurrence: lc.Occurrence, Before: lc.Before, After: lc.After}
178			}
179			fd.Corrections = append(fd.Corrections, cj)
180		}
181		for _, rec := range st.invalRecords {
182			ij := invalJSON{
183				ID:        rec.id,
184				Reason:    rec.reason,
185				Hash:      rec.hash,
186				Time:      rec.result.Time,
187				Landmarks: make([]invalLMJSON, len(rec.result.Landmarks)),
188			}
189			for i, l := range rec.result.Landmarks {
190				ij.Landmarks[i] = invalLMJSON{ID: l.ID, Occurrence: l.Occurrence}
191			}
192			fd.Invalidations = append(fd.Invalidations, ij)
193		}
194		payload, err := json.Marshal(&fd)
195		if err != nil {
196			return nil, fmt.Errorf("posemap: encode state: %w", err)
197		}
198	
199		out := make([]byte, headerLen+len(payload)+4)
200		copy(out[0:8], fileMagic)
201		binary.BigEndian.PutUint16(out[8:10], fileVersion)
202		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
203		copy(out[headerLen:], payload)
204		sum := crc32.ChecksumIEEE(out[:headerLen+len(payload)])
205		binary.BigEndian.PutUint32(out[headerLen+len(payload):], sum)
206		return out, nil
207	}
208	
209	// loadFile 只读取证地解析地图文件。
210	func loadFile(path string) (*mapState, error) {
211		raw, err := os.ReadFile(path)
212		if err != nil {
213			return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
214		}
215		if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
216			return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
217		}
218		version := binary.BigEndian.Uint16(raw[8:10])
219		if version != fileVersion {
220			return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
221		}
222		length := binary.BigEndian.Uint32(raw[10:14])
223		if int(length) != len(raw)-headerLen-4 {
224			return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
225		}
226		want := binary.BigEndian.Uint32(raw[len(raw)-4:])
227		if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
228			return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
229		}
230	
231		var fd fileData
232		if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
233			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
234		}
235		if err := validateLoaded(&fd); err != nil {
236			return nil, err
237		}
238	
239		st := &mapState{
240			config:       fd.Config,
241			trajectory:   fd.Trajectory,
242			landmarks:    make(map[string]*landmarkState, len(fd.Landmarks)),
243			segments:     make(map[string]*segmentRecord, len(fd.Segments)),
244			sources:      make([]*frameSource, len(fd.Trajectory)-1),
245			corrections:  make([]*CorrectionRecord, 0, len(fd.Corrections)),
246			corrIndex:    make(map[string]string, len(fd.Corrections)),
247			invalRecords: make([]*invalidationRecord, 0, len(fd.Invalidations)),
248			invalIndex:   make(map[string]*invalidationRecord, len(fd.Invalidations)),
249		}
250		// 旧文件不携带逐帧依据：有帧而 sources 缺省即旧地图。无帧时二者
251		// 无法区分也无需区分（尚无范围可校正）。
252		oldFormat := len(fd.Sources) == 0 && len(fd.Trajectory) > 1
253		for _, lmj := range fd.Landmarks {
254			lm := &landmarkState{}
255			if len(lmj.Occurrences) > 0 {
256				// 新格式：历次出现按编号递增保存。
257				for _, oj := range lmj.Occurrences {
258					lm.appearances = append(lm.appearances, &occurrenceState{
259						x:             oj.X,
260						y:             oj.Y,
261						count:         oj.Count,
262						legacyCount:   oj.LegacyCount,
263						legacyMX:      oj.LegacyMX,
264						legacyMY:      oj.LegacyMY,
265						firstSeenTime: oj.FirstSeenTime,
266						hasFirstSeen:  oj.HasFirstSeen,
267						active:        oj.Active,
268						invalidTime:   oj.InvalidTime,
269						invalidReason: oj.InvalidReason,
270						invalidOpID:   oj.InvalidOpID,
271					})
272				}
273			} else {
274				// 兼容旧布局：一个平铺路标即第 1 次有效出现。
275				occ := &occurrenceState{
276					x:      lmj.X,
277					y:      lmj.Y,
278					count:  lmj.Count,
279					active: true,
280				}
281				if oldFormat {
282					// 旧文件中该路标的全部既有观测都是固定旧贡献，位置取
283					// 文件中的聚合值；缺少逐帧来源，首次观测时间未知。
284					occ.legacyCount = lmj.Count
285					occ.legacyMX, occ.legacyMY = lmj.X, lmj.Y
286					occ.hasFirstSeen = false
287				} else {
288					occ.legacyCount = lmj.LegacyCount
289					occ.legacyMX, occ.legacyMY = lmj.LegacyMX, lmj.LegacyMY
290					// 含固定旧贡献时最早观测缺少来源，首次观测时间未知；
291					// 否则从逐帧依据中恢复该出现第一次被观测到的帧时间。
292					occ.hasFirstSeen = lmj.LegacyCount == 0
293					if occ.hasFirstSeen {
294						for k, src := range fd.Sources {
295							if src == nil {
296								continue
297							}
298							found := false
299							for _, ob := range src.Observations {
300								if ob.ID == lmj.ID {
301									found = true
302									break
303								}
304							}
305							if found {
306								occ.firstSeenTime = fd.Trajectory[k+1].Time
307								break
308							}
309						}
310					}
311				}
312				lm.appearances = append(lm.appearances, occ)
313			}
314			st.landmarks[lmj.ID] = lm
315		}
316		for _, sg := range fd.Segments {
317			ids := sg.Result.LandmarkIDs
318			if ids == nil {
319				ids = []string{}
320			}
321			st.segments[sg.ID] = &segmentRecord{
322				hash:   sg.Hash,
323				result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
324			}
325		}
326		if !oldFormat {
327			for k, src := range fd.Sources {
328				if src == nil {
329					continue // 来自旧文件的帧：保持依据缺失
330				}
331				obs := append([]Observation(nil), src.Observations...)
332				st.sources[k] = &frameSource{moveVariance: src.MoveVariance, observations: obs}
333			}
334		}
335		for _, cj := range fd.Corrections {
336			rec := &CorrectionRecord{
337				ID:        cj.ID,
338				Anchor:    cj.Anchor,
339				Target:    cj.Target,
340				EndTime:   cj.EndTime,
341				Poses:     make([]PoseChange, len(cj.Poses)),
342				Landmarks: make([]LandmarkChange, len(cj.Landmarks)),
343			}
344			for i, pc := range cj.Poses {
345				rec.Poses[i] = PoseChange{Before: pc.Before, After: pc.After}
346			}
347			for i, lc := range cj.Landmarks {
348				occNum := lc.Occurrence
349				if occNum == 0 {
350					occNum = 1 // 更早版本写出的校正记录不带编号，只有第 1 次出现
351				}
352				rec.Landmarks[i] = LandmarkChange{ID: lc.ID, Occurrence: occNum, Before: lc.Before, After: lc.After}
353			}
354			st.corrections = append(st.corrections, rec)
355			st.corrIndex[cj.ID] = canonicalCorrectionHash(cj.Anchor, cj.Target)
356		}
357		for _, ij := range fd.Invalidations {
358			lms := make([]InvalidatedLandmark, len(ij.Landmarks))
359			for i, l := range ij.Landmarks {
360				lms[i] = InvalidatedLandmark{ID: l.ID, Occurrence: l.Occurrence}
361			}
362			rec := &invalidationRecord{
363				id:     ij.ID,
364				reason: ij.Reason,
365				hash:   ij.Hash,
366				result: InvalidationResult{Time: ij.Time, Landmarks: lms},
367			}
368			st.invalRecords = append(st.invalRecords, rec)
369			st.invalIndex[ij.ID] = rec
370		}
371		return st, nil
372	}
373	
374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 各路标历次出现的时间边界：来源帧的观测归属核对与校正记录路标列表
477		// 核对共用同一份边界、同一套归属规则（见 occurrence.go）。旧文件缺省
478		// sources（解码为 nil）时不构建，两处核对都不进行。
479		var bounds map[string][]occurrenceWindow
480		if len(fd.Sources) != 0 {
481			bounds = make(map[string][]occurrenceWindow, len(fd.Landmarks))
482			for _, lm := range fd.Landmarks {
483				bounds[lm.ID] = occurrenceWindowsOf(lm)
484			}
485		}
486		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
487		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
488		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
489		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
490		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
491		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
492		if len(fd.Sources) != 0 {
493			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
494			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
495			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
496			// 也不能按帧数猜测。同时记录归属各次出现的最早来源观测帧时间，
497			// 供下方首次观测时间核对使用。
498			tallies := make(map[string]map[int]int, len(fd.Landmarks))
499			firstObs := make(map[string]map[int]int64, len(fd.Landmarks))
500			for k, src := range fd.Sources {
501				if src == nil {
502					continue // 旧地图帧：无逐帧依据，不要求补齐归属
503				}
504				t := fd.Trajectory[k+1].Time
505				for _, ob := range src.Observations {
506					wins, ok := bounds[ob.ID]
507					if !ok {
508						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
509					}
510					num := occurrenceNumberAt(wins, t)
511					if num == 0 {
512						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
513					}
514					c := tallies[ob.ID]
515					if c == nil {
516						c = make(map[int]int, 1)
517						tallies[ob.ID] = c
518					}
519					c[num]++
520					f := firstObs[ob.ID]
521					if f == nil {
522						f = make(map[int]int64, 1)
523						firstObs[ob.ID] = f
524					}
525					if cur, ok := f[num]; !ok || t < cur {
526						f[num] = t
527					}
528				}
529			}
530			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
531			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
532			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
533			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
534			// 次数，正常校正后保存的文件仍满足此不变量。
535			for _, lm := range fd.Landmarks {
536				if len(lm.Occurrences) == 0 {
537					// 旧版平铺路标即第 1 次出现。
538					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
539						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
540					}
541					continue
542				}
543				for _, oj := range lm.Occurrences {
544					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
545						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
546					}
547				}
548			}
549	
550			// 首次观测时间核对：首次观测时间已知、且全部观测都具有逐帧来源
551			// （无固定旧贡献）的每次出现，记录的首次时间必须准确等于实际归属
552			// 该次出现的最早来源观测帧时间。写早或写晚都是损坏：错误时间即使
553			// 恰好命中某个已保存的帧，只要该帧没有观测这一路标也不能接受；
554			// 错误时间没有对应帧同样拒绝。各次出现分别核对——已失效的旧出现
555			// 与失效后再现的新出现各自依据自己的观测判断，不能互相代替；后续
556			// 帧继续观测或同帧重复观测都不改变首次时间。时间为零或负数是合法
557			// 帧时间，按实际值比较，不把零当作时间未知。旧文件第 1 次出现缺
558			// 少旧观测依据、首次时间未知（HasFirstSeen 为假），或仍含固定旧
559			// 贡献时，其最早观测无从核对，保留旧地图的既有打开规则；但旧路标
560			// 失效后新导入产生的出现依据完整、首次时间已知，不因同一文件存在
561			// 旧历史而跳过核对。回环校正只改位姿与位置，不改观测帧时间，已正
562			// 确保存的校正地图仍满足此不变量。
563			for _, lm := range fd.Landmarks {
564				for _, oj := range lm.Occurrences {
565					if !oj.HasFirstSeen || oj.LegacyCount > 0 {
566						continue
567					}
568					// 次数核对已保证 Count-LegacyCount 条来源观测存在，最早
569					// 帧时间必然已记录；缺失本身即矛盾。
570					first, ok := firstObs[lm.ID][oj.Number]
571					if !ok || first != oj.FirstSeenTime {
572						return fmt.Errorf("%w: landmark %s occurrence %d records first seen time %d but its earliest sourced observation is at frame time %d", ErrCorrupt, lm.ID, oj.Number, oj.FirstSeenTime, first)
573					}
574				}
575			}
576	
577			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
578			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
579			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
580			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
581			// 空观测帧不增加贡献。转换、接纳、增量平均与计数全部复用导入/校正
582			// 的同一规则（见 aggregate.go），旧文件固定旧贡献（LegacyCount 次
583			// 平均）作为聚合起点——不能当成零，也不能用缺少依据的帧数代替。
584			// 回环校正后保存的文件按当前轨迹重放即得到当前位置，不要求等于校正
585			// 记录里的历史快照；各次出现分别核对，已失效的出现同样核对。合并
586			// 距离只是导入/校正时的接纳门槛，不是保存位置偏差的容许范围：重放
587			// 中出现非有限结果或距离冲突，或最终平均位置与保存位置不完全一致，
588			// 都按损坏拒绝。纯旧文件没有 sources、null 旧帧没有依据，均不重放。
589			type posKey struct {
590				id  string
591				num int
592			}
593			posAggs := make(map[posKey]*observationAgg, len(fd.Landmarks))
594			seedPosAgg := func(id string, num, legacyCount int, lx, ly float64) {
595				a := &observationAgg{}
596				if legacyCount > 0 {
597					a.seed(legacyCount, lx, ly)
598				}
599				posAggs[posKey{id: id, num: num}] = a
600			}
601			for _, lm := range fd.Landmarks {
602				if len(lm.Occurrences) == 0 {
603					// 旧版平铺路标即第 1 次出现。
604					seedPosAgg(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
605					continue
606				}
607				for _, oj := range lm.Occurrences {
608					seedPosAgg(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
609				}
610			}
611			for k, src := range fd.Sources {
612				if src == nil {
613					continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
614				}
615				pose := fd.Trajectory[k+1]
616				for _, ob := range src.Observations {
617					// 归属（存在性与时间边界）已在上面校验，num 必非 0。
618					num := occurrenceNumberAt(bounds[ob.ID], pose.Time)
619					a := posAggs[posKey{id: ob.ID, num: num}]
620					switch a.admit(pose, ob, fd.Config.MergeDistance) {
621					case obsNonFinite:
622						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, ob.ID, num, pose.Time)
623					case obsConflict:
624						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, ob.ID, num, pose.Time)
625					}
626				}
627			}
628			checkPosition := func(id string, num int, x, y float64) error {
629				a := posAggs[posKey{id: id, num: num}]
630				// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
631				// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
632				if a.x != x || a.y != y {
633					return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
634				}
635				return nil
636			}
637			for _, lm := range fd.Landmarks {
638				if len(lm.Occurrences) == 0 {
639					if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
640						return err
641					}
642					continue
643				}
644				for _, oj := range lm.Occurrences {
645					if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
646						return err
647					}
648				}
649			}
650		}
651		segIDs := make(map[string]struct{}, len(fd.Segments))
652		for _, sg := range fd.Segments {
653			if sg.ID == "" || sg.Hash == "" {
654				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
655			}
656			if _, dup := segIDs[sg.ID]; dup {
657				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
658			}
659			segIDs[sg.ID] = struct{}{}
660		}
661		corrIDs := make(map[string]struct{}, len(fd.Corrections))
662		// corrOccKey 标识校正范围内被观测涉及的某个路标某一次出现。
663		type corrOccKey struct {
664			id  string
665			num int
666		}
667		for _, cr := range fd.Corrections {
668			if cr.ID == "" || cr.Anchor > cr.EndTime {
669				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
670			}
671			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
672			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
673			// 校验为严格递增，命中即唯一。
674			anchorIdx, endIdx := -1, -1
675			for j := 1; j < len(fd.Trajectory); j++ {
676				if fd.Trajectory[j].Time == cr.Anchor {
677					anchorIdx = j
678				}
679				if fd.Trajectory[j].Time == cr.EndTime {
680					endIdx = j
681				}
682			}
683			if anchorIdx < 0 || endIdx < 0 {
684				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
685			}
686			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
687			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
688			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
689			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
690			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
691			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
692			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
693			if len(cr.Poses) != endIdx-anchorIdx+1 {
694				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
695			}
696			for i, pc := range cr.Poses {
697				ft := fd.Trajectory[anchorIdx+i].Time
698				if pc.Before.Time != ft || pc.After.Time != ft {
699					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
700				}
701				if !finitePose(pc.Before) || !finitePose(pc.After) {
702					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
703				}
704			}
705			// 以下两项核对都只针对范围内逐帧依据完整的校正：范围内任一来源
706			// 帧为 null 旧帧时保留旧文件的既有打开规则，不推测运动方差、也
707			// 不把未知贡献当成零；纯旧文件缺省 sources（长度为 0，bounds 同
708			// 时为 nil）时所有记录都不核对。同一文件中其余依据完整的记录不
709			// 受含旧帧记录影响，仍逐一核对。
710			fullyBased := len(fd.Sources) != 0
711			if fullyBased {
712				for k := anchorIdx - 1; k <= endIdx-1; k++ {
713					if fd.Sources[k] == nil {
714						fullyBased = false
715						break
716					}
717				}
718			}
719			if fullyBased {
720				// 校正后方差核对：锚点帧的校正后方差必须等于该次提交的目标
721				// 方差；其后每帧在目标方差上，按时间顺序累加锚点之后至该帧
722				// 的原运动方差。锚点自身进入该帧的运动方差不再加一次，也不
723				// 能以校正前方差作为起点；累计范围以本记录自己的锚点与结束
724				// 时间为准，后来对重叠范围的再校正与之后追加的帧都不属于本
725				// 记录。目标方差或参与累计的运动方差为负/非有限、累计结果非
726				// 有限，或与保存的校正后方差不完全一致，都按损坏拒绝整份文
727				// 件——每一帧逐一核对，不能只凭锚点与末帧正确就接受中间错误
728				// 的记录；目标方差与运动方差全为零的合法校正同样逐帧通过。
729				accum := cr.Target.Variance
730				if !isFinite(accum) || accum < 0 {
731					return fmt.Errorf("%w: correction %s target variance is negative or non-finite", ErrCorrupt, cr.ID)
732				}
733				for i, pc := range cr.Poses {
734					if i > 0 {
735						// 记录内第 i 帧位于轨迹下标 anchorIdx+i；进入它的运
736						// 动方差在来源 sources[anchorIdx+i-1]（i=1 即锚点之
737						// 后第一帧），锚点自身的来源 sources[anchorIdx-1] 不
738						// 参与累计。
739						mv := fd.Sources[anchorIdx+i-1].MoveVariance
740						if !isFinite(mv) || mv < 0 {
741							return fmt.Errorf("%w: correction %s accumulates negative or non-finite motion variance at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
742						}
743						accum += mv
744						if !isFinite(accum) {
745							return fmt.Errorf("%w: correction %s corrected variance accumulates to non-finite value at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
746						}
747					}
748					if pc.After.Variance != accum {
749						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected variance %v but target variance %v and the motion variances after the anchor accumulate to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Variance, cr.Target.Variance, accum)
750					}
751				}
752				// 几何核对：整条记录必须描述同一次平移和旋转。只核对该记录
753				// 自身保存的校正前后值与目标，不要求历史快照等于当前轨迹——
754				// 后来对重叠范围再校正、或在结束时间之后追加轨迹，都不改写旧
755				// 记录，也不能使原本合法的旧记录被拒绝。旋转角、余弦正弦与
756				// 期望位姿的运算次序与 Correct 提交时完全一致（见
757				// correction.go），本包写出的合法记录重算出的期望值与保存值
758				// 逐位相同；这里另按容差接纳浮点重算误差。锚点的校正后位置
759				// 必须是目标位置、朝向必须是目标朝向归一到 [-π,π) 的结果；
760				// 其余帧必须与锚点一起做同一次刚体重定位：保留校正前相对锚
761				// 点的位置关系与朝向差。每一帧都逐一核对——只有锚点与末帧
762				// 正确而中间一帧位置偏离或单独转向，同样按损坏拒绝；范围只有
763				// 锚点一帧时本核对即只针对该帧。坐标容差为 1e-9 乘以
764				// 1、期望值绝对值、保存值绝对值三者的最大值；朝向按最短角
765				// 度差比较，容差 1e-9 弧度。容差与路标合并距离无关：合并距
766				// 离只是导入/校正时的观测接纳门槛，不能用来放过记录内部的
767				// 几何矛盾。目标位置/朝向与锚点校正前完全相同（角度等价）
768				// 时是恒等（只调方差）校正，期望几何直接取校正前值，与
769				// Correct 的同一分支保持一致：横跨 ±1e308 的轨迹上“相对锚
770				// 点偏移”会溢出，不能因此把合法的恒等校正误判为损坏。
771				anchorBefore := cr.Poses[0].Before
772				newHeading := normalizeAngle(cr.Target.Heading)
773				dHeading := normalizeAngle(newHeading - anchorBefore.Heading)
774				cosD, sinD := math.Cos(dHeading), math.Sin(dHeading)
775				identity := dHeading == 0 && cr.Target.X == anchorBefore.X && cr.Target.Y == anchorBefore.Y
776				for i, pc := range cr.Poses {
777					var wantX, wantY, wantHeading float64
778					switch {
779					case i == 0:
780						wantX, wantY, wantHeading = cr.Target.X, cr.Target.Y, newHeading
781					case identity:
782						wantX, wantY, wantHeading = pc.Before.X, pc.Before.Y, pc.Before.Heading
783					default:
784						dx := pc.Before.X - anchorBefore.X
785						dy := pc.Before.Y - anchorBefore.Y
786						wantX = cr.Target.X + cosD*dx - sinD*dy
787						wantY = cr.Target.Y + sinD*dx + cosD*dy
788						wantHeading = normalizeAngle(pc.Before.Heading + dHeading)
789					}
790					if !coordClose(pc.After.X, wantX) {
791						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected x %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.X, wantX)
792					}
793					if !coordClose(pc.After.Y, wantY) {
794						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected y %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Y, wantY)
795					}
796					if !angleClose(pc.After.Heading, wantHeading) {
797						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected heading %v but the record's rotation makes it %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Heading, wantHeading)
798					}
799				}
800			}
801			for _, lc := range cr.Landmarks {
802				if lc.ID == "" {
803					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
804				}
805				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
806					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
807					lc.Before.Count < 1 || lc.After.Count < 1 {
808					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
809				}
810			}
811			// 路标列表必须恰好描述记录范围（锚点帧到结束帧，两端包含；之后
812			// 追加的帧不属于范围）内逐帧观测实际涉及的路标出现：范围内被观测
813			// 到的每个（路标，出现编号）必须恰好有一条前后记录，同一次出现被
814			// 多帧或同帧多条观测涉及也只记一条；少记、多记、重复、或把出现
815			// 编号改指该范围没有涉及的另一出现，都按损坏拒绝整份文件，而不是
816			// 只看条目里的坐标与次数是否合法。归属沿用与来源校验相同的时间边
817			// 界规则：同一标识失效后再现属于不同出现，即使位置相同也分别对应；
818			// 已失效的旧出现只要范围内（含失效时刻）有它的观测就必须在列表
819			// 中，不因当前区域查询不再返回它而被排除；范围外帧（如记录之后
820			// 才再现的新出现）的观测不计入。范围内没有任何路标观测时列表必须
821			// 为空，非空即损坏。仅对范围内逐帧依据完整的校正做此核对：范围内
822			// 含 null 旧帧的校正缺少逐帧依据，保留旧地图的既有打开规则，不凭
823			// 推测要求补造观测。
824			if bounds != nil && fullyBased {
825				want := make(map[corrOccKey]struct{})
826				for j := anchorIdx; j <= endIdx; j++ {
827					t := fd.Trajectory[j].Time
828					for _, ob := range fd.Sources[j-1].Observations {
829						// 归属已在上方的来源校验中确认（路标存在、必有唯一
830						// 接纳出现），这里同样计算以保持两处规则一致。
831						want[corrOccKey{id: ob.ID, num: occurrenceNumberAt(bounds[ob.ID], t)}] = struct{}{}
832					}
833				}
834				got := make(map[corrOccKey]struct{}, len(cr.Landmarks))
835				for _, lc := range cr.Landmarks {
836					num := lc.Occurrence
837					if num == 0 {
838						num = 1 // 更早版本写出的校正记录不带编号，按第 1 次出现解释
839					}
840					wins, ok := bounds[lc.ID]
841					if !ok || num < 1 || num > len(wins) {
842						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d not touched by its range", ErrCorrupt, cr.ID, lc.ID, num)
843					}
844					key := corrOccKey{id: lc.ID, num: num}
845					if _, dup := got[key]; dup {
846						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d more than once", ErrCorrupt, cr.ID, lc.ID, num)
847					}
848					got[key] = struct{}{}
849				}
850				for key := range want {
851					if _, ok := got[key]; !ok {
852						return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
853					}
854				}
855				for key := range got {
856					if _, ok := want[key]; !ok {
857						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
858					}
859				}
860			}
861			if _, dup := corrIDs[cr.ID]; dup {
862				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
863			}
864			corrIDs[cr.ID] = struct{}{}
865		}
866		// 路标记录按标识索引，供失效记录与出现历史的交叉核对使用。
867		lmByID := make(map[string]*landmarkJSON, len(fd.Landmarks))
868		for i := range fd.Landmarks {
869			lmByID[fd.Landmarks[i].ID] = &fd.Landmarks[i]
870		}
871		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
872		// invalTriples 记录每条失效操作实际引用的（操作标识，路标，出现编号）
873		// 三元组，供反向核对：每个已失效出现都必须是某条操作记录里的实际条目。
874		type invalTriple struct {
875			op  string
876			lm  string
877			num int
878		}
879		invalTriples := make(map[invalTriple]struct{}, len(fd.Invalidations))
880		for _, iv := range fd.Invalidations {
881			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
882				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
883			}
884			if _, dup := invalIDs[iv.ID]; dup {
885				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
886			}
887			invalIDs[iv.ID] = struct{}{}
888			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
889			for _, l := range iv.Landmarks {
890				if l.ID == "" || l.Occurrence < 1 {
891					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
892				}
893				if _, dup := lmSeen[l.ID]; dup {
894					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
895				}
896				lmSeen[l.ID] = struct{}{}
897			}
898			// 交叉核对：成功失效结果里的每个（路标标识，出现编号）必须准确
899			// 指向该路标历史中同编号的那次出现，不能改指同一路标的其他出现，
900			// 也不能因为路标后来再次出现就把旧结果指向最新记录。被指出现必须
901			// 已经失效，且其上记录的失效操作标识、失效时间、失效原因都与这条
902			// 操作记录一致——时间与原因各自再合理也不够，实际由另一条操作撤下
903			// 时不能仅凭相同时间/原因认可。旧版平铺路标视为第 1 次有效出现，
904			// 不可能被失效记录引用（引用即损坏）。一条操作同时撤下多个路标时，
905			// 任意一个条目不满足对应关系都拒绝打开整个文件。
906			for _, l := range iv.Landmarks {
907				lm := lmByID[l.ID]
908				if lm == nil {
909					return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
910				}
911				if len(lm.Occurrences) == 0 {
912					return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
913				}
914				if l.Occurrence > len(lm.Occurrences) {
915					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
916				}
917				// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
918				oj := lm.Occurrences[l.Occurrence-1]
919				if oj.Active {
920					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
921				}
922				if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
923					return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
924				}
925				invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
926			}
927		}
928		// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
929		// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
930		// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
931		// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
932		// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
933		// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
934		// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
935		for _, lm := range fd.Landmarks {
936			for _, oj := range lm.Occurrences {
937				if oj.Active {
938					continue
939				}
940				if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
941					return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
942				}
943			}
944		}
945		return nil
946	}
947	
948	func finitePose(p Pose) bool {
949		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
950	}
951	
952	// geomTol 是打开时核对校正记录几何一致性的相对容差（另含 1 的绝对项）。
953	const geomTol = 1e-9
954	
955	// coordClose 判断保存坐标 got 是否在容许误差内等于期望 want：误差不得
956	// 超过 geomTol 乘以 1、|want|、|got| 三者中的最大值。参与比较的值都已
957	// 校验为有限，差值必有限，NaN 不会混入并被误当相等。
958	func coordClose(got, want float64) bool {
959		scale := math.Max(1, math.Max(math.Abs(want), math.Abs(got)))
960		return math.Abs(got-want) <= geomTol*scale
961	}
962	
963	// angleClose 按最短角度差判断两个角度是否相等，容差 geomTol 弧度。两个
964	// 角度都已校验为有限；差值经归一化到 [-π,π) 即最短角度差，正确处理
965	// ±π 附近跨边界但物理方向相同的情形。
966	func angleClose(got, want float64) bool {
967		return math.Abs(normalizeAngle(got-want)) <= geomTol
968	}
969	
970	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
971	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
972	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
973		h := sha256.New()
974		var b [8]byte
975		binary.BigEndian.PutUint64(b[:], uint64(anchor))
976		h.Write(b[:])
977		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
978			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
979			h.Write(b[:])
980		}
981		return fmt.Sprintf("%x", h.Sum(nil))
982	}
983	
984	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
985	func (m *Map) saveExclusive() error {
986		data, err := encodeFile(m.state)
987		if err != nil {
988			return err
989		}
990		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
991		if err != nil {
992			return err
993		}
994		return writeAndClose(f, data, m.path)
995	}
996	
997	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
998	func (m *Map) saveReplace() (err error) {
999		data, err := encodeFile(m.state)
1000		if err != nil {
1001			return err
1002		}
1003		dir, base := filepath.Split(m.path)
1004		if dir == "" {
1005			dir = "."
1006		}
1007		f, err := os.CreateTemp(dir, base+".tmp-*")
1008		if err != nil {
1009			return err
1010		}
1011		tmpName := f.Name()
1012		// 任何失败路径都尽力清理临时文件。
1013		defer func() {
1014			if err != nil {
1015				_ = os.Remove(tmpName)
1016			}
1017		}()
1018		if err = writeAndClose(f, data, tmpName); err != nil {
1019			return err
1020		}
1021		if err = os.Rename(tmpName, m.path); err != nil {
1022			return err
1023		}
1024		return nil
1025	}
1026	
1027	func writeAndClose(f *os.File, data []byte, name string) (err error) {
1028		defer func() {
1029			if cerr := f.Close(); err == nil {
1030				err = cerr
1031			}
1032		}()
1033		if _, err = f.Write(data); err != nil {
1034			return err
1035		}
1036		if err = f.Sync(); err != nil {
1037			return err
1038		}
1039		return nil
1040	}
1041	
1042	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
1043	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
1044	func canonicalHash(frames []Frame) string {
1045		h := sha256.New()
1046		var lenBuf [4]byte
1047		var numBuf [8]byte
1048		putU32 := func(v uint32) {
1049			binary.BigEndian.PutUint32(lenBuf[:], v)
1050			h.Write(lenBuf[:])
1051		}
1052		putU64 := func(v uint64) {
1053			binary.BigEndian.PutUint64(numBuf[:], v)
1054			h.Write(numBuf[:])
1055		}
1056		putStr := func(s string) {
1057			putU32(uint32(len(s)))
1058			h.Write([]byte(s))
1059		}
1060	
1061		putU32(uint32(len(frames)))
1062		for _, fr := range frames {
1063			putU64(uint64(fr.Time))
1064			putU64(math.Float64bits(fr.DX))
1065			putU64(math.Float64bits(fr.DY))
1066			putU64(math.Float64bits(fr.DHeading))
1067			putU64(math.Float64bits(fr.MoveVariance))
1068			putU32(uint32(len(fr.Observations)))
1069			for _, ob := range fr.Observations {
1070				putStr(ob.ID)
1071				putU64(math.Float64bits(ob.X))
1072				putU64(math.Float64bits(ob.Y))
1073			}
1074		}
1075		return fmt.Sprintf("%x", h.Sum(nil))
1076	}
1077

