253		h, _ = m.LandmarkAppearances("L")
254		if len(h.Appearances) != 2 {
255			t.Fatalf("want 2 appearances, got %d: %+v", len(h.Appearances), h)
256		}
257		if h.Appearances[0].Number != 1 || h.Appearances[0].Active {
258			t.Fatalf("occurrence 1 changed: %+v", h.Appearances[0])
259		}
260		a2 := h.Appearances[1]
261		if a2.Number != 2 || !a2.Active || a2.Landmark.Count != 1 || a2.Landmark.X != 1e308 || a2.Landmark.Y != 0 {
262			t.Fatalf("reappearance = %+v, want #2 active count 1 at (1e308,0)", a2)
263		}
264	
265		// 落盘结果一致：重开后状态相同，且 s2 已作为成功段记录。
266		if err := m.Close(); err != nil {
267			t.Fatal(err)
268		}
269		m2, err := Open(path)
270		if err != nil {
271			t.Fatal(err)
272		}
273		defer m2.Close()
274		cur, _ = m2.CurrentPose()
275		if cur.Time != 2 {
276			t.Fatalf("after reopen current time = %d", cur.Time)
277		}
278		h2, err := m2.LandmarkAppearances("L")
279		if err != nil || len(h2.Appearances) != 2 || !h2.Appearances[1].Active || h2.Appearances[1].Landmark.Count != 1 {
280			t.Fatalf("after reopen appearances: %+v %v", h2, err)
281		}
282		// 同 ID 同内容重复导入返回首次结果。
283		if _, err := m2.ImportSegment(Segment{ID: "s2", Frames: []Frame{
284			{Time: 2, Observations: []Observation{{ID: "L", X: 0}}},
285		}}); err != nil {
286			t.Fatalf("duplicate import after reopen: %v", err)
287		}
288	}
289	
290	// 大坐标本身不受限制：位姿在 1e308 处保持有限即接受，同一路标连续两次
291	// 转换到同一地图坐标 (1e308,0) 合并后仍是 (1e308,0)、次数 2。
292	func TestImportHugeButFiniteAccepted(t *testing.T) {
293		m := newMap(t, Config{
294			InitialTime: 0, InitialX: 1e308, InitialY: 0, InitialHeading: 0,
295			InitialVariance: 1e308, MaxInterval: 100, MergeDistance: 10,
296		})
297		res, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
298			{Time: 1, MoveVariance: 0, Observations: []Observation{{ID: "L", X: 0, Y: 0}}},
299			{Time: 2, MoveVariance: 0, Observations: []Observation{{ID: "L", X: 0, Y: 0}}},
300		}})
301		if err != nil {
302			t.Fatalf("ImportSegment: %v", err)
303		}
304		if res.EndPose.X != 1e308 || res.EndPose.Variance != 1e308 {
305			t.Fatalf("end pose = %+v, want X=1e308 variance 1e308", res.EndPose)
306		}
307		lms, _ := m.LandmarksInRect(Rect{MinX: 0, MinY: -1, MaxX: math.MaxFloat64, MaxY: 1})
308		if len(lms) != 1 || lms[0].X != 1e308 || lms[0].Y != 0 || lms[0].Count != 2 {
309			t.Fatalf("landmark = %+v, want (1e308,0) count 2", lms)
310		}
311	}
