185			})
186		}
187	}
188	
189	// 坐标容差为 1e-9 乘以 1、|期望|、|保存| 三者最大值：坐标量级约 10 时容差
190	// 约 1e-8，半档误差放行、两倍档误差拒绝；朝向容差为 1e-9 弧度的绝对最短
191	// 角度差，半档放行、两倍档拒绝。放行时原样返回被保存的值，不借容差改写
192	// 快照。
193	func TestOpenCorrectionGeometryTolerance(t *testing.T) {
194		// 坐标：中间帧期望 x=10，容差 ~1e-8。
195		coordCases := []struct {
196			name    string
197			perturb float64
198			wantOK  bool
199		}{
200			{"within half tolerance", 5e-9, true},
201			{"beyond tolerance", 2e-8, false},
202		}
203		for _, tc := range coordCases {
204			t.Run("coord "+tc.name, func(t *testing.T) {
205				path := filepath.Join(t.TempDir(), "m.pose")
206				buildGeometryMap(t, path, 10)
207				tamperFile(t, path, func(fd *fileData) {
208					fd.Corrections[0].Poses[1].After.X = 10 + tc.perturb
209				})
210				if tc.wantOK {
211					m, err := Open(path)
212					if err != nil {
213						t.Fatalf("within tolerance should open: %v", err)
214					}
215					recs, _ := m.Corrections()
216					if got := recs[0].Poses[1].After.X; got != 10+tc.perturb {
217						t.Fatalf("snapshot rewritten to %v, want saved %v", got, 10+tc.perturb)
218					}
219					m.Close()
220				} else {
221					assertOpenCorrupt(t, path)
222				}
223			})
224		}
225	
226		// 朝向：中间帧期望朝向 0，容差为绝对 1e-9 弧度。
227		angleCases := []struct {
228			name    string
229			perturb float64
230			wantOK  bool
231		}{
232			{"within half tolerance", 5e-10, true},
233			{"beyond tolerance", 2e-9, false},
234		}
235		for _, tc := range angleCases {
236			t.Run("angle "+tc.name, func(t *testing.T) {
237				path := filepath.Join(t.TempDir(), "m.pose")
238				buildGeometryMap(t, path, 10)
239				tamperFile(t, path, func(fd *fileData) {
240					fd.Corrections[0].Poses[1].After.Heading = tc.perturb
241				})
242				if tc.wantOK {
243					m, err := Open(path)
244					if err != nil {
245						t.Fatalf("within angle tolerance should open: %v", err)
246					}
247					m.Close()
248				} else {
249					assertOpenCorrupt(t, path)
250				}
251			})
252		}
253	}
254	
255	// 大坐标下容差随量级放宽：坐标量级 1e10 时容差约 10，偏移 5 放行、偏移 20
256	// 拒绝。
257	func TestOpenCorrectionGeometryRelativeToleranceLargeCoordinates(t *testing.T) {
258		build := func(t *testing.T) string {
259			path := filepath.Join(t.TempDir(), "m.pose")
260			m, err := Create(path, Config{
261				InitialTime: 0, MaxInterval: 100, MergeDistance: 10,
262			})
263			if err != nil {
264				t.Fatal(err)
265			}
266			// p100=(1,0,h=0) p200=(3,0,h=0) p300=(5,0,h=0)，无旋转。
267			if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
268				{Time: 100, DX: 1},
269				{Time: 200, DX: 2},
270				{Time: 300, DX: 2},
271			}}); err != nil {
272				t.Fatal(err)
273			}
274			if _, err := m.Correct(Correction{ID: "c1", Anchor: 100,
275				Target: CorrectionTarget{X: 1e10, Y: 0, Heading: 0, Variance: 1}}); err != nil {
276				t.Fatal(err)
277			}
278			if err := m.Close(); err != nil {
279				t.Fatal(err)
280			}
281			return path
282		}
283		for _, tc := range []struct {
284			name   string
285			shift  float64
286			wantOK bool
287		}{
288			{"shift 5 within relative tolerance", 5, true},
289			{"shift 20 beyond relative tolerance", 20, false},
290		} {
291			t.Run(tc.name, func(t *testing.T) {
292				path := build(t)
293				fd := readFileData(t, path)
294				base := fd.Corrections[0].Poses[1].After.X // 中间帧校正后 x ≈ 1e10+2
295				fd.Corrections[0].Poses[1].After.X = base + tc.shift
296				writeFileDataRaw(t, path, &fd)
297				if tc.wantOK {
298					m, err := Open(path)
299					if err != nil {
300						t.Fatalf("within relative tolerance should open: %v", err)
301					}
302					m.Close()
303				} else {
304					assertOpenCorrupt(t, path)
305				}
306			})
307		}
308	}
309	
310	// 超过容差的几何矛盾不能因为路标合并距离很大而被接受：合并距离只用于导入/
311	// 校正时的观测接纳，不是记录内部几何偏差的容许范围。
312	func TestOpenCorrectionGeometryRejectedRegardlessOfMergeDistance(t *testing.T) {
313		path := filepath.Join(t.TempDir(), "m.pose")
314		buildGeometryMap(t, path, 1e9)
315		tamperFile(t, path, func(fd *fileData) {
316			// 中间帧位置偏离 0.5：远小于 1e9 的合并距离，但远超 1e-8 容差。
317			fd.Corrections[0].Poses[1].After.X = 10.5
318		})
319		assertOpenCorrupt(t, path)
320	}
321	
322	// 朝向按最短角度差比较、容差 1e-9 弧度：归一化使 -π 与 +π 指向同一方向，
323	// 跨越 ±π 边界但物理等价（差在容差内）的写法放行；跨边界后差 1e-8 拒绝。
324	// 这里用 δ=-π 的校正，使锚点与其余帧的校正后朝向都为 -π。
325	func TestOpenCorrectionGeometryShortestAngle(t *testing.T) {
326		build := func(t *testing.T) string {
327			path := filepath.Join(t.TempDir(), "m.pose")
328			m, err := Create(path, Config{
329				InitialTime: 0, MaxInterval: 100, MergeDistance: 10,
330			})
331			if err != nil {
332				t.Fatal(err)
333			}
334			if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
335				{Time: 100, DX: 1},
336				{Time: 200, DX: 1},
337			}}); err != nil {
338				t.Fatal(err)
339			}
340			if _, err := m.Correct(Correction{ID: "c1", Anchor: 100,
341				Target: CorrectionTarget{X: 5, Y: 0, Heading: math.Pi, Variance: 1}}); err != nil {
342				t.Fatal(err)
343			}
344			if err := m.Close(); err != nil {
345				t.Fatal(err)
346			}
347			return path
348		}
349		for _, tc := range []struct {
350			name   string
351			fn     func(fd *fileData)
352			wantOK bool
353		}{
354			{"minus pi and plus pi are the same direction", func(fd *fileData) {
355				fd.Corrections[0].Poses[0].After.Heading = math.Pi
356			}, true},
357			{"seam gap within tolerance", func(fd *fileData) {
358				fd.Corrections[0].Poses[1].After.Heading = math.Pi - 5e-10
359			}, true},
360			{"seam gap beyond tolerance", func(fd *fileData) {
361				fd.Corrections[0].Poses[0].After.Heading = math.Pi - 1e-8
362			}, false},
363		} {
364			t.Run(tc.name, func(t *testing.T) {
365				path := build(t)
366				tamperFile(t, path, tc.fn)
367				if tc.wantOK {
368					m, err := Open(path)
369					if err != nil {
370						t.Fatalf("shortest-angle equivalent heading should open: %v", err)
371					}
372					m.Close()
373				} else {
374					assertOpenCorrupt(t, path)
375				}
376			})
377		}
378	}
379	
380	// 只调方差、位置与朝向都不变的恒等校正，在轨迹坐标横跨 ±1e308 时仍正常
381	// 打开：几何核对与 Correct 走同一恒等分支，不重算会溢出的相对锚点偏移。
382	func TestOpenAcceptsIdentityCorrectionGeometryHugeSpan(t *testing.T) {
383		path := filepath.Join(t.TempDir(), "m.pose")
384		m, err := Create(path, Config{
385			InitialTime: 0, InitialX: -1e308, InitialY: 0, InitialHeading: 0,
386			InitialVariance: 1, MaxInterval: 100, MergeDistance: 10,
387		})
388		if err != nil {
389			t.Fatal(err)
390		}
391		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
392			{Time: 100, DX: 0, MoveVariance: 0.25},
393			{Time: 200, DX: 1e308, MoveVariance: 0.5},
394			{Time: 300, DX: 1e308, MoveVariance: 0.75},
395		}}); err != nil {
396			t.Fatal(err)
397		}
398		if _, err := m.Correct(Correction{ID: "c", Anchor: 100,
399			Target: CorrectionTarget{X: -1e308, Y: 0, Heading: 0, Variance: 4}}); err != nil {
400			t.Fatal(err)
401		}
402		if err := m.Close(); err != nil {
403			t.Fatal(err)
404		}
405		m2, err := Open(path)
406		if err != nil {
407			t.Fatalf("identity correction across ±1e308 must open: %v", err)
408		}
409		m2.Close()
410	
411		// 恒等记录中一帧的校正后位置被改成另一个有限值仍按几何矛盾拒绝。
412		tamperFile(t, path, func(fd *fileData) {
413			fd.Corrections[0].Poses[1].After.X = 1.0
414		})
415		assertOpenCorrupt(t, path)
416	}
417	
418	// 核对只针对记录自身保存的校正前后值与目标：旧记录之后对重叠范围再次校正、
419	// 或在结束时间之后追加轨迹，都不改变旧记录保存的快照，旧记录仍合法打开。
420	func TestOpenCorrectionGeometryUsesRecordSnapshotsOnly(t *testing.T) {
421		path := filepath.Join(t.TempDir(), "m.pose")
422		buildGeometryMap(t, path, 10)
423	
424		// 重开后把锚点 100 再校正到另一目标，并追加一帧：旧记录 c1 的快照与
425		// 当前轨迹不再一致，但其自身描述的仍是同一次平移和旋转。
426		m, err := Open(path)
427		if err != nil {
428			t.Fatal(err)
429		}
430		if _, err := m.Correct(Correction{ID: "c2", Anchor: 100,
431			Target: CorrectionTarget{X: -3, Y: -4, Heading: math.Pi / 4, Variance: 7}}); err != nil {
432			t.Fatal(err)
433		}
434		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{{Time: 400, DX: 1}}}); err != nil {
435			t.Fatal(err)
436		}
437		if err := m.Close(); err != nil {
438			t.Fatal(err)
439		}
440	
441		m2, err := Open(path)
442		if err != nil {
443			t.Fatalf("older record must stay valid after recorrection and appended frames: %v", err)
444		}
445		defer m2.Close()
446		recs, _ := m2.Corrections()
447		if len(recs) != 2 || recs[0].ID != "c1" || recs[1].ID != "c2" {
448			t.Fatalf("records = %+v", recs)
449		}
450		if got := recs[0].Poses[1].After; got.X != 10 || got.Y != 18 {
451			t.Fatalf("old record snapshot changed: %+v", got)
452		}
453	}
454	
455	// 校正范围内含缺少逐帧依据的 null 旧帧时，几何核对与方差核对一样保留旧
456	// 打开规则：即使记录的几何明显矛盾也不补造依据、不拒绝；同一文件中另一条
457	// 依据完整的记录仍须核对，其几何矛盾时整份文件按损坏拒绝。
458	func TestOpenSkipsGeometryCheckForNullBasisRecords(t *testing.T) {
459		path := filepath.Join(t.TempDir(), "m.pose")
460		m, err := Create(path, Config{
461			InitialTime: 0, MaxInterval: 100, MergeDistance: 10,
462		})
463		if err != nil {
464			t.Fatal(err)
465		}
466		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
467			{Time: 100, DX: 1},
468			{Time: 200, DX: 1},
469			{Time: 300, DX: 1},
470		}}); err != nil {
471			t.Fatal(err)
472		}
473		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100,
474			Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
475			t.Fatal(err)
476		}
477		if err := m.Close(); err != nil {
478			t.Fatal(err)
479		}
480	
481		// t=200 的逐帧依据置空，并把 c1 中间帧改成任意几何矛盾值：范围含 null
482		// 旧帧，沿用旧规则放行，记录原样保留。
483		tamperFile(t, path, func(fd *fileData) {
484			fd.Sources[1] = nil
485			fd.Corrections[0].Poses[1].After.X = 500
486		})
487		m2, err := Open(path)
488		if err != nil {
489			t.Fatalf("record spanning null basis frame keeps legacy open rules: %v", err)
490		}
491	
492		// 追加依据完整的新帧，并只对该帧提交一帧校正（范围不含 null 帧）。
493		if _, err := m2.ImportSegment(Segment{ID: "s2", Frames: []Frame{{Time: 400, DX: 1}}}); err != nil {
494			t.Fatal(err)
495		}
496		if _, err := m2.Correct(Correction{ID: "c2", Anchor: 400,
497			Target: CorrectionTarget{X: 9, Y: 9, Variance: 2}}); err != nil {
498			t.Fatal(err)
499		}
500		if err := m2.Close(); err != nil {
501			t.Fatal(err)
502		}
503	
504		// c1 几何矛盾但依据不完整（跳过），c2 依据完整且合法：正常打开。
505		m3, err := Open(path)
506		if err != nil {
507			t.Fatalf("reopen: %v", err)
508		}
509		recs, _ := m3.Corrections()
510		if len(recs) != 2 || recs[0].Poses[1].After.X != 500 ||
511			recs[1].Poses[0].After.X != 9 {
512			t.Fatalf("records = %+v", recs)
513		}
514		m3.Close()
515	
516		// c2 唯一一帧几何与目标矛盾：其余记录被跳过不影响，整份文件仍拒绝。
517		tamperFile(t, path, func(fd *fileData) {
518			fd.Corrections[1].Poses[0].After.X = 9.5
519		})
520		assertOpenCorrupt(t, path)
521	}
522	
523	// 几何矛盾时 Open 返回的错误可被 errors.Is 识别为 ErrCorrupt。
524	func TestOpenGeometryErrorIsErrCorrupt(t *testing.T) {
525		path := filepath.Join(t.TempDir(), "m.pose")
526		buildGeometryMap(t, path, 10)
527		tamperFile(t, path, func(fd *fileData) {
528			fd.Corrections[0].Poses[2].After.Heading = 1
529		})
530		_, err := Open(path)
531		if !errors.Is(err, ErrCorrupt) {
532			t.Fatalf("err = %v, want errors.Is ErrCorrupt", err)
533		}
534	}
