113	
114				// 初始位姿（时间 0、原坐标、方差 1）不改变，也不进校正记录。
115				p0, err := m.PoseAt(0)
116				if err != nil {
117					t.Fatalf("PoseAt(0): %v", err)
118				}
119				if p0.Time != 0 || p0.X != ac.initX || p0.Y != ac.initY || p0.Heading != 0 || p0.Variance != 1 {
120					t.Fatalf("initial pose changed: %+v", p0)
121				}
122			})
123		}
124	}
125	
126	// 恒等校正仍生成完整校正记录：锚点至提交时末帧的前后位姿齐全；该范围内被
127	// 观测路标的各次出现都有条目，前后位置相同也保留，位置、观测次数、出现编号
128	// 与有效状态不变。之后再次校正不改写已有记录。
129	func TestCorrectionVarianceOnlyRecord(t *testing.T) {
130		m := newMap(t, Config{
131			InitialTime: 0, InitialX: -1e308, InitialY: 0, InitialHeading: 0,
132			InitialVariance: 1, MaxInterval: 100,
133			// 相邻观测的地图坐标相隔最大 1.5e308，合并距离需覆盖。
134			MergeDistance: 1.6e308,
135		})
136		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
137			{Time: 100, DX: 0, MoveVariance: 0.25, Observations: []Observation{{ID: "L"}}},
138			{Time: 200, DX: 1e308, MoveVariance: 0.5, Observations: []Observation{{ID: "L"}}},
139			{Time: 300, DX: 1e308, MoveVariance: 0.75, Observations: []Observation{{ID: "L"}}},
140		}}); err != nil {
141			t.Fatal(err)
142		}
143	
144		rec, err := m.Correct(Correction{ID: "c", Anchor: 100,
145			Target: CorrectionTarget{X: -1e308, Y: 0, Heading: 0, Variance: 4}})
146		if err != nil {
147			t.Fatalf("Correct: %v", err)
148		}
149		if rec.EndTime != 300 || len(rec.Poses) != 3 {
150			t.Fatalf("record = end %d poses %d, want end 300 and 3 poses", rec.EndTime, len(rec.Poses))
151		}
152		// 路标条目保留：前后位置相同也必须有条目，次数/编号不变。
153		if len(rec.Landmarks) != 1 {
154			t.Fatalf("landmark changes = %d, want 1 retained even with equal before/after", len(rec.Landmarks))
155		}
156		lc := rec.Landmarks[0]
157		if lc.ID != "L" || lc.Occurrence != 1 {
158			t.Fatalf("landmark change = %+v, want L occurrence 1", lc)
159		}
160		if lc.Before.X != lc.After.X || lc.Before.Y != lc.After.Y {
161			t.Fatalf("landmark moved on identity correction: %+v -> %+v", lc.Before, lc.After)
162		}
163		if lc.Before.Count != 3 || lc.After.Count != 3 {
164			t.Fatalf("landmark count = %d -> %d, want 3 unchanged", lc.Before.Count, lc.After.Count)
165		}
166	
167		// 查询与历次出现立即反映：位置/次数/编号/有效状态保持原值。
168		lms, _ := m.LandmarksInRect(Rect{MinX: -1, MinY: -1, MaxX: 1, MaxY: 1})
169		if len(lms) != 1 || lms[0].ID != "L" || lms[0].X != 0 || lms[0].Y != 0 || lms[0].Count != 3 {
170			t.Fatalf("landmark query after correction = %+v, want L at (0,0) count 3", lms)
171		}
172		h, err := m.LandmarkAppearances("L")
173		if err != nil || len(h.Appearances) != 1 {
174			t.Fatalf("appearances = %+v err=%v, want exactly 1", h, err)
175		}
176		a := h.Appearances[0]
177		if !a.Active || a.Number != 1 || a.Landmark.Count != 3 || a.FirstSeenTime != 100 {
178			t.Fatalf("appearance changed: %+v", a)
179		}
180	
181		// 再次校正只追加新记录，不改写首条。
182		rec2, err := m.Correct(Correction{ID: "c2", Anchor: 200,
183			Target: CorrectionTarget{X: 0, Y: 0, Heading: 0, Variance: 9}})
184		if err != nil {
185			t.Fatalf("second correction: %v", err)
186		}
187		if len(rec2.Poses) != 2 {
188			t.Fatalf("second record poses = %d, want 2 (200..300)", len(rec2.Poses))
189		}
190		all, _ := m.Corrections()
191		if len(all) != 2 || all[0].ID != "c" || all[1].ID != "c2" {
192			t.Fatalf("corrections = %+v, want c then c2, first never rewritten", all)
193		}
194		if len(all[0].Poses) != 3 || all[0].Poses[0].After.Variance != 4 {
195			t.Fatalf("first record rewritten: %+v", all[0])
196		}
197	}
198	
199	// 恒等校正只放宽“几何相同但相对偏移计算溢出”这一种误拒绝；其余拒绝规则不变：
200	// 负方差、非有限目标、有限目标但累计后非有限（标明锚点时间）、真正改变位置
201	// 或朝向的校正保留原有 non_finite 行为。任何拒绝不留部分更新。
202	func TestCorrectionVarianceOnlyRejections(t *testing.T) {
203		build := func(t *testing.T, merge float64) *Map {
204			m := newMap(t, Config{
205				InitialTime: 0, InitialX: -1e308, InitialY: 0, InitialHeading: 0,
206				InitialVariance: 1, MaxInterval: 100, MergeDistance: merge,
207			})
208			if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
209				{Time: 100, DX: 0, MoveVariance: 0.25},
210				{Time: 200, DX: 1e308, MoveVariance: 0.5},
211				{Time: 300, DX: 1e308, MoveVariance: 0.75},
212			}}); err != nil {
213				t.Fatal(err)
214			}
215			return m
216		}
217	
218		// 溢出专用：锚点之后一帧携带 1e308 的运动方差。
219		buildOverflow := func(t *testing.T) *Map {
220			m := newMap(t, Config{
221				InitialTime: 0, InitialX: -1e308, InitialY: 0, InitialHeading: 0,
222				InitialVariance: 1, MaxInterval: 100, MergeDistance: 10,
223			})
224			if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
225				{Time: 100, DX: 0, MoveVariance: 0},
226				{Time: 200, DX: 1e308, MoveVariance: 1e308},
227				{Time: 300, DX: 1e308, MoveVariance: 0},
228			}}); err != nil {
229				t.Fatal(err)
230			}
231			return m
232		}
233	
234		t.Run("negative variance", func(t *testing.T) {
235			m := build(t, 10)
236			_, err := m.Correct(Correction{ID: "x", Anchor: 100,
237				Target: CorrectionTarget{X: -1e308, Variance: -0.01}})
238			r, ok := AsRejectError(err)
239			if !ok || r.Kind != RejectNegativeVariance || !r.HasTime || r.Time != 100 {
240				t.Fatalf("err = %v, want negative_variance at anchor 100", err)
241			}
242		})
243	
244		t.Run("non-finite target variance", func(t *testing.T) {
245			m := build(t, 10)
246			_, err := m.Correct(Correction{ID: "x", Anchor: 100,
247				Target: CorrectionTarget{X: -1e308, Variance: math.NaN()}})
248			r, ok := AsRejectError(err)
249			if !ok || r.Kind != RejectNonFinite || !r.HasTime || r.Time != 100 {
250				t.Fatalf("err = %v, want non_finite at anchor 100", err)
251			}
252		})
253	
254		t.Run("finite target variance accumulates to infinity", func(t *testing.T) {
255			m := buildOverflow(t)
256			// 目标方差本身有限；与锚点之后帧 200 的 1e308 运动方差累计即溢出。
257			_, err := m.Correct(Correction{ID: "x", Anchor: 100,
258				Target: CorrectionTarget{X: -1e308, Variance: 1e308}})
259			r, ok := AsRejectError(err)
260			if !ok || r.Kind != RejectNonFinite || !r.HasTime || r.Time != 100 {
261				t.Fatalf("err = %v, want non_finite marked with anchor time 100", err)
262			}
263			// 原子性：方差、位置、校正记录保持原值。
264			cur, _ := m.CurrentPose()
265			if cur.Variance != 1e308 || cur.X != 1e308 {
266				t.Fatalf("state changed after rejection: %+v", cur)
267			}
268			if p, _ := m.PoseAt(100); p.Variance != 1 {
269				t.Fatalf("anchor variance changed after rejection: %v", p.Variance)
270			}
271			if recs, _ := m.Corrections(); len(recs) != 0 {
272				t.Fatalf("correction record leaked: %+v", recs)
273			}
274		})
275	
276		t.Run("heading change keeps arithmetic rejection", func(t *testing.T) {
277			m := build(t, 10)
278			// 位置不变但朝向改变：相对偏移 2e308 旋转后溢出，保留原有 non_finite。
279			_, err := m.Correct(Correction{ID: "x", Anchor: 100,
280				Target: CorrectionTarget{X: -1e308, Heading: math.Pi, Variance: 4}})
281			r, ok := AsRejectError(err)
282			if !ok || r.Kind != RejectNonFinite || !r.HasTime || r.Time != 100 {
283				t.Fatalf("err = %v, want non_finite at anchor 100 for heading change", err)
284			}
285			if p, _ := m.PoseAt(100); p.Heading != 0 || p.Variance != 1.25 {
286				t.Fatalf("anchor changed after rejection: %+v", p)
287			}
288		})
289	
290		t.Run("position change keeps arithmetic rejection", func(t *testing.T) {
291			m := build(t, 10)
292			// 朝向不变但位置确实改变：1e308 量级下 ULP 约 1.6e292，+1 会被舍掉
293			// （数值上仍是同一锚点位姿），取可分辨的 1e293；远端帧相对偏移仍溢出。
294			_, err := m.Correct(Correction{ID: "x", Anchor: 100,
295				Target: CorrectionTarget{X: -1e308 + 1e293, Variance: 4}})
296			r, ok := AsRejectError(err)
297			if !ok || r.Kind != RejectNonFinite || !r.HasTime || r.Time != 100 {
298				t.Fatalf("err = %v, want non_finite at anchor 100 for position change", err)
299			}
300			if p, _ := m.PoseAt(300); p.X != 1e308 || p.Variance != 2.5 {
301				t.Fatalf("pose changed after rejection: %+v", p)
302			}
303		})
304	}
305	
306	// 恒等校正落盘后重开：位置与新方差、校正记录（锚点至末帧的前后位姿）一致。
307	func TestCorrectionVarianceOnlyPersists(t *testing.T) {
308		path := filepath.Join(t.TempDir(), "map.bin")
309		m, err := Create(path, Config{
310			InitialTime: 0, InitialX: -1e308, InitialY: 0, InitialHeading: 0,
311			InitialVariance: 1, MaxInterval: 100, MergeDistance: 10,
312		})
313		if err != nil {
314			t.Fatal(err)
315		}
316		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
317			{Time: 100, DX: 0, MoveVariance: 0.25},
318			{Time: 200, DX: 1e308, MoveVariance: 0.5},
319			{Time: 300, DX: 1e308, MoveVariance: 0.75},
320		}}); err != nil {
321			t.Fatal(err)
322		}
323		if _, err := m.Correct(Correction{ID: "c", Anchor: 100,
324			Target: CorrectionTarget{X: -1e308, Variance: 4}}); err != nil {
325			t.Fatalf("Correct: %v", err)
326		}
327		if err := m.Close(); err != nil {
328			t.Fatal(err)
329		}
330	
331		m2, err := Open(path)
332		if err != nil {
333			t.Fatal(err)
334		}
335		defer m2.Close()
336		want := []struct {
337			tm       int64
338			x        float64
339			variance float64
340		}{{100, -1e308, 4}, {200, 0, 4.5}, {300, 1e308, 5.25}}
341		for _, w := range want {
342			p, err := m2.PoseAt(w.tm)
343			if err != nil {
344				t.Fatalf("PoseAt(%d) after reopen: %v", w.tm, err)
345			}
346			if p.X != w.x || p.Y != 0 || p.Heading != 0 || p.Variance != w.variance {
347				t.Fatalf("after reopen PoseAt(%d) = %+v, want X=%v variance %v", w.tm, p, w.x, w.variance)
348			}
349		}
350		recs, _ := m2.Corrections()
351		if len(recs) != 1 || recs[0].ID != "c" || len(recs[0].Poses) != 3 {
352			t.Fatalf("after reopen corrections = %+v, want one record c with 3 poses", recs)
353		}
354	}
